script:
const want = ctx.val('trang_thai', 'Hoàn tất xử lý');
const isDone = /hoàn tất/i.test(want);
const note = ctx.testPrefix + ' ' + ctx.val('ghi_chu', 'Đã kiểm tra và xử lý xong phiếu IoT');
const dlg = page.locator('[role=dialog]');

await step('Mở chi tiết phiếu IoT cần xử lý', async () => {
  await page.waitForLoadState('networkidle', { timeout: 20000 }).catch(() => {});
  const allTab = page.getByText('Tất cả', { exact: true }).first();
  if (await allTab.waitFor({ timeout: 10000 }).then(() => true).catch(() => false)) await allTab.click();
  const target = ctx.val('phieu', '') || ctx.testPrefix;
  const row = page.getByText(target).first();
  await row.waitFor({ timeout: 25000 });
  await row.click();
  await page.waitForURL(/\/iot\/(doing|create)\/detail\//, { timeout: 20000 });
});

await step('Tiếp nhận hoặc Hoàn tất phiếu IoT', async () => {
  const btnReceive = page.getByText('Tiếp nhận phiếu', { exact: true }).first();
  if (await btnReceive.isVisible().catch(() => false)) {
    await btnReceive.click();
    await dlg.waitFor({ timeout: 10000 });
    await dlg.getByText('Xác nhận', { exact: true }).click();
    await dlg.waitFor({ state: 'hidden', timeout: 15000 });
  }
  if (isDone) {
    const btnDone = page.getByText('Hoàn tất phiếu', { exact: true }).first();
    if (await btnDone.waitFor({ timeout: 15000 }).then(() => true).catch(() => false)) {
      await btnDone.click();
      await dlg.waitFor({ timeout: 10000 });
      const box = dlg.locator('textarea').first();
      if (await box.count()) { await box.click(); await box.pressSequentially(note); }
      await dlg.getByText('Hoàn tất', { exact: true }).click();
      await dlg.waitFor({ state: 'hidden', timeout: 15000 });
    }
  }
});
ctx.log('Đã thực hiện xử lý phiếu IoT theo trạng thái: ' + want);
